const mails = await api.get("/mails", { label: "complaint" });
const out = [];
for (const m of mails.items) {
  if (!m.customer_id) { out.push({ mail_id: m.id, customer_id: null, tier: "고객 연결 없음" }); continue; }
  const c = await api.get(`/customers/${m.customer_id}`);
  out.push({ mail_id: m.id, customer_id: m.customer_id, tier: c.tier ?? "정보 없음" });
}
return out;

